const subs=subjectNames.map((v,i)=>({code:String(i+1).padStart(2,'0'),short:v[0],name:v[1],vi:v[2],tone:v[3],tint:v[4],modules:I.filter(m=>m.subject_code===String(i+1).padStart(2,'0'))}));const sm=Object.fromEntries(subs.map(x=>[x.code,x]));const subjectOf=id=>id.slice(6,8);const codeOf=l=>l.module.subject_code;const answerKey=(id,i)=>prefix+id+':'+i;function ans(id,i){let x=parse(read(answerKey(id,i)),null);return Number.isInteger(x)&&x>=0&&x<=2?x:null}function getCount(l){let n=0;for(let i=0;i<l.n;i++)if(ans(l.id,i)!==null)n++;return n}function status(l){return S.read[l.id]?'Đã học':getCount(l)?'Đang học':'Chưa học'}function counts(ls){let done=0,n=0,total=0;for(const l of ls){if(S.read[l.id])done++;n+=getCount(l);total+=l.n}return{done,n,total}}function knownWrong(){return Object.entries(S.marks).filter(([k,v])=>v&&v.wrong===true&&meta[k.split(':')[0]])}function dueCards(){return Object.entries(S.cards).filter(([k,v])=>v&&v.due<=Date.now()&&meta[k.split(':')[0]])}
