function route(){let h=location.hash.slice(1);if(!h){let p=new URLSearchParams(location.search);if(p.get('module')){let m=I.find(x=>x.id===p.get('module'));if(m){let l=m.los.find(x=>x.id.endsWith(p.get('los')||'__'))||m.los[0];return ['lesson',l.id]}}return['home']}let [p,...r]=h.split('/');return[p,...r.map(x=>{try{return decodeURIComponent(x)}catch{return x}})]}function link(p,...r){return '#'+[p,...r.map(encodeURIComponent)].join('/')}function go(p,...r){let h=link(p,...r);if(location.hash===h)render();else location.hash=h}function toast(msg){$('toast').textContent=msg;$('toast').className='show';clearTimeout(toast.t);toast.t=setTimeout(()=>$('toast').className='',3500)}function toggleTheme(){S.dark=!S.dark;save();document.documentElement.classList.toggle('dark',S.dark);toast(S.dark?'Đã bật giao diện tối':'Đã bật giao diện sáng')}
const btn=(txt,act,cls='')=>`<button type="button" class="btn ${cls}" data-act="${esc(act)}">${txt}</button>`;const bar=(a,b)=>`<div class="progress" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${pct(a,b)}" aria-label="Tiến độ"><span style="width:${pct(a,b)}%"></span></div>`;const badge=(txt,cls='')=>`<span class="pill ${cls}">${esc(txt)}</span>`;const si=s=>`<div class="subject-icon" style="--tone:${s.tone};--tint:${s.tint}">${s.short}</div>`;const hrefLesson=(l,tab='learn')=>link('lesson',l.id,tab);
function shell(page){let active=['course','lesson','search'].includes(page)?'book':page;document.documentElement.classList.toggle('dark',S.dark);$('sidebar').innerHTML=`<a class="brand" href="#home"><span class="brand-mark">S</span><span><strong>Study Hub</strong><small>CFA Level I · 2026</small></span></a><button class="side-close" type="button" data-act="menu" aria-label="Ẩn thanh điều hướng">‹ Ẩn menu</button><div class="nav-caption">Học tập</div>${NAV.map(([k,t],i)=>`${i===6?'<div class="nav-caption">Công cụ</div>':''}<a class="nav-link ${active===k?'active':''}" href="#${k}">${icon(k)}${t}</a>`).join('')}<div class="side-bottom">Học theo tốc độ của bạn<br><a href="legacy.html">Kho học liệu cũ · chưa xác minh ↗</a></div>`;$('topbar').innerHTML=`<button class="icon-btn mobile-menu" data-act="menu" aria-controls="sidebar" aria-expanded="true" aria-label="Ẩn/hiện thanh điều hướng">${icon('menu')}</button><div class="top-title">${pages[page]||'Study Hub'}</div><form id="search-form" class="top-search" role="search">${icon('search')}<input name="q" aria-label="Tìm bài học" placeholder="Tìm bài học…" autocomplete="off"></form><button class="icon-btn" data-act="theme" aria-label="Đổi giao diện sáng tối">${icon('moon')}</button><div class="avatar" title="Hồ sơ học trên thiết bị">ME</div>`;let b=$('mobile-bottom');if(!b){b=document.createElement('nav');b.id='mobile-bottom';b.className='mobile-bottom';b.setAttribute('aria-label','Điều hướng nhanh');document.querySelector('.workspace').append(b)}b.innerHTML=[['home','Trang chủ'],['book','Môn học'],['sourcebank','Tài liệu gốc'],['review','Ôn tập']].map(([k,t])=>`<button data-act="nav:${k}" class="${active===k?'active':''}">${icon(k==='sourcebank'?'book':k)}${t}</button>`).join('');if(!$('overlay')){let d=document.createElement('div');d.id='overlay';d.className='nav-overlay';d.dataset.act='menu';document.body.append(d)}document.body.classList.remove('nav-open');syncSidebar()}
